/** Embedded Paul Motor palmetto logo (JPEG) for PDF/HTML — no filesystem needed on Vercel. */
export const PALMETTO_LOGO_JPEG_BASE64 =
  "";

export function palmettoLogoJpegBytes(): Uint8Array {
  if (typeof Buffer !== "undefined") {
    return new Uint8Array(Buffer.from(PALMETTO_LOGO_JPEG_BASE64, "base64"));
  }
  const bin = atob(PALMETTO_LOGO_JPEG_BASE64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

export const PALMETTO_LOGO_DATA_URI =
  "data:image/jpeg;base64," + PALMETTO_LOGO_JPEG_BASE64;
